import { useState } from 'react';

function Panel({ title, isActive, onShow }) {
  return <section><h2>{title}</h2>{isActive ? <p>Details</p> : <button onClick={onShow}>Show</button>}</section>;
}

export default function Accordion() {
  const [activeId, setActiveId] = useState('profile');
  return (
    <>
      <Panel title="Profile" isActive={activeId === 'profile'} onShow={() => setActiveId('profile')} />
      <Panel title="Security" isActive={activeId === 'security'} onShow={() => setActiveId('security')} />
    </>
  );
}
```
Accordion owns the changing selection as state. Each Panel receives its current status and an event callback as props.

